import axios from 'axios';

const BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';

const apiClient = axios.create({
  baseURL: BASE_URL,
  timeout: 30000,
});

// ─── Request interceptor ────────────────────────────────────────────────────
apiClient.interceptors.request.use(
  (config) => {
    // Attach auth token if available
    const token = localStorage.getItem('vio_token');
    if (token) config.headers.Authorization = `Bearer ${token}`;
    return config;
  },
  (error) => Promise.reject(error)
);

// ─── Response interceptor ───────────────────────────────────────────────────
apiClient.interceptors.response.use(
  (response) => response,
  (error) => {
    const message =
      error.response?.data?.message ||
      error.response?.data?.error ||
      error.message ||
      'An unexpected error occurred';
    return Promise.reject(new Error(message));
  }
);

// ─── API Methods ────────────────────────────────────────────────────────────

/**
 * Detect helmet violation from an image blob or file.
 * @param {File|Blob} imageFile
 * @returns {Promise<DetectionResult>}
 *
 * Expected response shape from Flask:
 * {
 *   vehicle_number: "TS09AB1234",
 *   helmet_detected: false,
 *   violation: true,
 *   confidence: 0.94,
 *   detected_image_url: "...",   // optional
 *   timestamp: "2025-03-18T..."
 * }
 */
export const detectViolation = async (imageFile) => {
  const formData = new FormData();
  formData.append('image', imageFile);

  const response = await apiClient.post('/detect', formData, {
    headers: { 'Content-Type': 'multipart/form-data' },
    onUploadProgress: (progressEvent) => {
      // Can expose this via a progress callback if needed
      const pct = Math.round((progressEvent.loaded * 100) / progressEvent.total);
      console.debug(`Upload progress: ${pct}%`);
    },
  });

  return response.data;
};

export default apiClient;
